(() => {
 const M=SIMM_MATH,m=x=>'$'+x.toFixed(3)+'m',n=x=>x.toFixed(3),a=(id,label,min,max,step,value,unit='USD m')=>({id,label,min,max,step,value,unit}),sel=(id,label,options,value)=>({id,label,options,value});
 const pdf='https://www.isda.org/a/hhkiE/ISDA-SIMM_v2.82512_PUBLIC.pdf',refs={method:[pdf,'ISDA methodology 2.8+2512 · effective 11 July 2026'],data:['https://www.isda.org/isda-solutions-infohub/common-risk-interchange-format/','ISDA · Common Risk Interchange Format'],gov:['https://www.isda.org/a/BoqE/20220715_ISDA-SIMM-Governance-Framework.pdf','ISDA · governance framework'],margin:['https://www.bis.org/bcbs/publ/d499.htm','BCBS–IOSCO · non-cleared margin framework']};
 const out=(labels,values,rows,explanation,stats)=>({stats:stats||labels.slice(0,3).map((l,i)=>[l,m(values[i])]),bars:labels.map((label,i)=>({label,value:values[i],color:['#285e46','#7597ac','#b68744','#80a666'][i%4]})),headers:['Step','Value','Why it matters'],rows,explanation,note:'Amounts are USD millions unless labelled otherwise. Adjustable risk weights, thresholds and correlations are teaching assumptions unless explicitly identified as prescribed.'});
 window.SIMM_LESSONS=[];
 function add(x){SIMM_LESSONS.push({stage:'01 · Why initial margin exists',chart:'Follow the margin mechanism',simpleTitle:'Build the intuition',key:'Synthetic sensitivities. Model formulas follow the cited section; the reduced examples do not implement every SIMM exception or a complete calibration.',notes:[],sources:[refs.method],...x});}
 window.SIMM_UI={M,m,n,a,sel,out,add,refs};
 add({id:'overview',name:'IM versus VM',title:'Today’s exposure and tomorrow’s uncertainty need different buffers.',intro:'Separate the current mark-to-market from an assumed adverse move during the close-out period.',inputs:[a('mtm','Current amount owed to you',0,20,.5,5),a('loss','Adverse close-out move',0,20,.5,8),a('im','IM held',0,20,.5,6)],challenge:'Set current exposure to zero. Can an adverse future move still leave a loss?',formula:'Current exposure is covered by VM.\nIllustrative remaining close-out loss = max(adverse move − IM, 0)',simple:'VM settles the exposure already visible in prices. IM is a separate buffer for the market movement that could occur while a defaulted portfolio is closed out. A trade worth zero today can still be risky tomorrow.',scope:'Single adverse scenario, fully settled VM, no collateral haircut or disputes. The chosen IM is an input, not a SIMM calculation. Regulatory scope and agreements determine actual obligations.',sources:[refs.margin,refs.method],compute(s){return out(['VM','IM buffer','Uncovered move'],[s.mtm,s.im,Math.max(s.loss-s.im,0)],[['Current exposure',m(s.mtm),'Assumed covered by VM'],['Future adverse movement',m(s.loss),'After the VM snapshot'],['Remaining loss',m(Math.max(s.loss-s.im,0)),'No guarantee against every possible outcome']],`VM of ${m(s.mtm)} covers today. The separate ${m(s.im)} IM buffer absorbs part or all of the ${m(s.loss)} future move.`);}});
 add({id:'horizon',name:'Horizon and confidence',title:'A longer close-out gives uncertainty more time to grow.',intro:'Explore a Gaussian benchmark for why a 10-day, 99% margin target differs from ordinary daily volatility.',inputs:[a('sd','One-day loss standard deviation',.1,5,.1,1),a('days','Illustrative holding period',1,20,1,10,'business days'),sel('z','Confidence quantile',[['1.644854','95%'],['2.326348','99%'],['2.575829','99.5%']],'2.326348')],challenge:'Double the holding period. Does this simplified margin double?',formula:'Gaussian benchmark = z × daily standard deviation × √days',simple:'Closing a portfolio is a process, not an instantaneous sale. More time usually creates more opportunity for adverse moves. The confidence target describes coverage over repeated outcomes, not a promise that losses stop at the margin amount.',scope:'Independent Gaussian daily increments with constant volatility. SIMM is calibrated to a 10-day, 99% objective; it is not calculated by applying this slider formula to a portfolio’s daily P&L. Stressed calibration and non-linear risk matter.',sources:[refs.margin,['https://www.isda.org/a/C8RgE/ISDA-SIMM-The-Trusted-Standard-for-Initial-Margin-Calculations.pdf','ISDA · SIMM overview']],compute(s){return out(['Daily SD','Horizon SD','Tail benchmark'],[s.sd,s.sd*Math.sqrt(s.days),s.sd*Math.sqrt(s.days)*Number(s.z)],[['Holding period',s.days,'Business days in this benchmark'],['Quantile',s.z,'Not an adjustable production SIMM setting']],`At ${s.days} days, the benchmark is ${m(s.sd*Math.sqrt(s.days)*Number(s.z))}. Fat tails, jumps and illiquidity can violate square-root-of-time intuition.`);}});
 add({id:'hierarchy',name:'Product classes and risk classes',title:'A risk hedge is not always an eligible margin hedge.',intro:'Place two equal-and-opposite rate exposures inside one product class or across two product classes.',inputs:[a('risk','Weighted rate exposure',0,20,.5,8),a('hedge','Opposite weighted exposure',0,20,.5,6),sel('same','Where does the hedge belong?',[['yes','Same product class and netting set'],['no','Different product class or netting set']],'yes')],challenge:'Keep the economic hedge unchanged and move it to another product class.',formula:'Same exact risk factor and eligible set: |A − B|\nSeparate product classes / netting sets: |A| + |B|',simple:'SIMM first respects legal and product boundaries. The four product classes are RatesFX, Credit, Equity and Commodity. Each can contain several of the six risk classes: an equity option can carry equity, rates and FX risk, all retained within its Equity product class.',scope:'Two exposures to the identical factor; already weighted, no concentration. The separate case illustrates forbidden cross-boundary offsets, not a trade classification choice for optimisation. Actual classification follows the instrument.',compute(s){const net=Math.abs(s.risk-s.hedge),sep=s.risk+s.hedge;return out(['Eligible net','Separate sum','Selected result'],[net,sep,s.same==='yes'?net:sep],[['Four product classes','RatesFX / Credit / Equity / Commodity','Calculate separately, then add'],['Six risk classes','IR / Credit Q / Credit non-Q / Equity / Commodity / FX','Aggregate within each product class']],`Selected result is ${m(s.same==='yes'?net:sep)}. Never move a trade to a false product class merely to manufacture an offset.`);}});
 add({id:'units',name:'Sensitivity signs and units',stage:'02 · From trades to weighted risk',title:'A small unit error can create a huge margin error.',intro:'Convert a finite price change into a per-basis-point sensitivity before applying a risk weight.',inputs:[a('change','Signed value change in bump',-1,1,.01,.1),a('bump','Rate bump used',1,100,1,10,'bp'),a('rw','Illustrative rate risk weight',1,150,1,60,'bp')],challenge:'Keep the same per-bp risk by doubling both the bump and price change.',formula:'s per bp = ΔV / bump in bp\nWeighted sensitivity = s × RW',simple:'A risk number is meaningful only with its bump convention, sign and currency. Reporting the value change for a 10 bp bump as a 1 bp sensitivity exaggerates risk tenfold. Equity and FX use a percentage-move convention; vega needs an additional volatility convention.',scope:'Linear finite-difference approximation for rate risk. SIMM sensitivity definitions are in section C; this lesson is not a universal conversion for every Greek or asymmetric option bump.',compute(s){const sens=s.change/s.bump,w=sens*s.rw;return out(['Bump P&L','Per-bp risk','Weighted risk'],[s.change,sens,w],[['Per-bp sensitivity',m(sens)+'/bp','Divide by the actual bump'],['Risk weight',s.rw+' bp','Illustrative shock scale'],['Standalone magnitude',m(Math.abs(w)),'Retain signed WS until aggregation']],`The correct weighted sensitivity is ${m(w)}. Treating the whole bump P&L as per-bp risk would produce ${m(s.change*s.rw)}.`);}});
 add({id:'netting',name:'Net before weighting',stage:'02 · From trades to weighted risk',title:'An exact offset should disappear before concentration is measured.',intro:'Combine two signed sensitivities to the same eligible factor and compare net with gross processing.',inputs:[a('a','Trade A sensitivity',0,20,.5,10),a('b','Trade B sensitivity',-20,0,.5,-8),a('t','Concentration threshold',1,20,.5,5),a('rw','Illustrative weight multiplier',.1,2,.1,1,'×')],challenge:'Make B exactly offset A. What happens to net sensitivity and concentration?',formula:'s = sA + sB; CR = max(1, √(|s|/T)); WS = RW × s × CR',simple:'SIMM measures the residual risk after permitted offsets. Counting each trade separately can create a concentration charge on a risk that the portfolio does not actually hold. Similar names, different tenors and separate legal sets are not exact offsets.',scope:'One non-IR factor, same product class and netting set. Both records use consistent units and qualifiers.',compute(s){const net=s.a+s.b,c=M.cr(net,s.t),v=Math.abs(net*s.rw*c),gross=Math.abs(s.a*s.rw*M.cr(s.a,s.t))+Math.abs(s.b*s.rw*M.cr(s.b,s.t));return out(['Net margin','Gross processing'],[v,gross],[['Net sensitivity',n(net),'Sum signed risk first'],['CR',n(c),'Apply threshold to eligible net amount'],['Gross approach',m(gross),'Comparison only: wrong for an exact eligible offset']],`The residual sensitivity is ${n(net)} and its concentration factor is ${n(c)}. Netting must happen at the correct risk-factor identity.`);}});
 add({id:'concentration',name:'Concentration and scaling',stage:'02 · From trades to weighted risk',title:'Beyond a threshold, doubling risk costs more than twice as much.',intro:'Scale one sensitivity and watch the concentration adjustment bend the margin curve.',inputs:[a('base','Base sensitivity',.1,10,.1,2),a('scale','Portfolio size multiplier',0,10,.5,3,'×'),a('t','Illustrative threshold',.5,20,.5,5)],challenge:'Compare doubling the book below and above the threshold.',formula:'CR = max(1, √(|s|/T)); |WS| = |s| × CR, with RW = 1',simple:'The square-root concentration uplift represents the difficulty of liquidating a large position. Below the threshold this example scales linearly. Above it, multiplying size also increases the concentration factor, creating a size-to-the-power-1.5 effect.',scope:'One risk factor with unit risk weight. Thresholds are currency-normalised sensitivity thresholds, not trade-notional limits. Actual aggregation groups vary by risk class and delta/vega.',compute(s){const x=s.base*s.scale,c=M.cr(x,s.t);return {stats:[['Net sensitivity',n(x)],['Concentration factor',n(c)+'×'],['Weighted magnitude',m(x*c)]],series:[{name:'With concentration',color:'#285e46',data:Array.from({length:41},(_,i)=>{const v=i/4*s.base;return [i/4,v*M.cr(v,s.t)]})},{name:'Linear comparison',color:'#7597ac',data:[[0,0],[10,s.base*10]]}],xlabel:'Portfolio size multiplier',headers:['Step','Value','Interpretation'],rows:[['Threshold',n(s.t),'Same units as sensitivity'],['Size / threshold',n(x/s.t),'Uplift begins above 1']],explanation:`At ${s.scale}× size, CR is ${n(c)}. This makes the weighted amount ${m(x*c)}.`};}});
 add({id:'bucket',name:'Within-bucket correlations',stage:'03 · Aggregation mechanics',title:'Opposite risks hedge less when they can move apart.',intro:'Change correlation between two weighted sensitivities in one bucket.',inputs:[a('a','Weighted sensitivity A',-20,20,.5,10),a('b','Weighted sensitivity B',-20,20,.5,-8),a('rho','Correlation',0,1,.05,.5,'ρ')],challenge:'Compare same-sign with opposite-sign exposures as correlation rises.',formula:'K = √(WSA² + WSB² + 2ρ WSA WSB)',simple:'Correlation controls how much common movement the model recognises. High correlation makes opposite positions better hedges, but makes same-direction positions behave more like one large bet. Correlation is prescribed in production, not selected to obtain a desired margin.',scope:'Two distinct factors; equal concentration factors, so the correlation concentration adjustment is 1. Negative correlations and larger prescribed matrices require class-specific treatment.',compute(s){const k=M.pair(s.a,s.b,s.rho);return out(['A','B','Bucket K'],[s.a,s.b,k],[['Sum of squares',n(s.a*s.a+s.b*s.b),'Always non-negative'],['Cross term',n(2*s.rho*s.a*s.b),'Can reduce or increase the square'],['K',m(k),'Square root of the total']],`The bucket requirement is ${m(k)}. The cross term ${s.a*s.b<0?'reduces':'increases'} the uncorrelated square when correlation rises.`);}});
 add({id:'correlation-adjustment',name:'Unequal concentration weakens offsets',stage:'03 · Aggregation mechanics',title:'A concentrated position does not inherit the full hedge correlation.',intro:'Observe weighting and the additional correlation adjustment for two non-IR factors.',inputs:[a('a','Sensitivity A',.5,20,.5,12),a('b','Sensitivity B',-20,0,.5,-3),a('t','Shared bucket threshold',1,20,.5,5),a('rho','Base correlation',0,1,.05,.8,'ρ')],challenge:'Increase A beyond the threshold while keeping the hedge small.',formula:'f = min(CRA, CRB) / max(CRA, CRB)\nK = √(WSA² + WSB² + 2ρf WSA WSB)',simple:'A large position and a small hedge may be difficult to unwind in tandem. SIMM both increases weighted risk and reduces the recognised correlation when their concentration factors differ. The adjustment can also reduce diversification cross terms for same-sign risks.',scope:'Two non-IR delta factors; unit weights. IR concentration is shared within currency and the adjustment appears across currencies. Vega uses its own thresholds and concentration groups.',compute(s){const r=M.bucket([s.a,s.b],1,s.t,s.rho);return out(['Weighted A','Weighted B','Bucket K'],[...r.w,r.k],[['CR A / B',r.c.map(n).join(' / '),'Different sizes can produce different uplifts'],['Adjustment f',n(r.f),'Ratio at most 1'],['Effective correlation',n(s.rho*r.f),'Base correlation × f']],`Effective correlation falls from ${n(s.rho)} to ${n(s.rho*r.f)}; bucket K is ${m(r.k)}.`);}});
 add({id:'across-buckets',name:'Across buckets and the S cap',stage:'03 · Aggregation mechanics',title:'Carry a bounded directional summary into the next layer.',intro:'Inspect why bucket K and the signed quantity S are different objects.',inputs:[a('k1','Bucket 1 K',0,20,.5,6),a('net','Bucket 1 sum of WS',-30,30,.5,12),a('k2','Bucket 2 K and positive S',0,20,.5,5),a('gamma','Across-bucket correlation',0,1,.05,.2,'γ'),a('res','Residual bucket K',0,10,.5,2)],challenge:'Increase the first sum beyond K. Why does the cross-bucket effect stop growing?',formula:'Sb = clamp(ΣWSb, −Kb, Kb)\nMargin = √(K1² + K2² + 2γ S1 S2) + Kresidual',simple:'K measures the bucket’s risk magnitude. S preserves direction for diversification with other buckets, but cannot exceed that magnitude. A residual bucket is added separately where the class has one; it does not obtain the ordinary cross-bucket offsets.',scope:'Diagnostic inputs K and sum are independently adjustable and may not all correspond to a real underlying portfolio. Two ordinary buckets plus an applicable residual bucket; no IR concentration adjustment here.',compute(s){const sb=M.clamp(s.net,-s.k1,s.k1),v=Math.sqrt(Math.max(0,s.k1*s.k1+s.k2*s.k2+2*s.gamma*sb*s.k2))+s.res;return out(['Raw sum','Capped S','Total margin'],[s.net,sb,v],[['S1',n(sb),'Bounded by ±K1'],['Ordinary buckets',m(v-s.res),'Diversified component'],['Residual',m(s.res),'Added outside the square root']],`The carried direction is ${n(sb)}, not ${n(s.net)}. The residual adds ${m(s.res)} without ordinary-bucket diversification.`);}});
 const classes=[
 ['ir','Interest-rate delta','Currency, curve and tenor all matter.','IR risk is organised by currency, then tenor and sub-curve. Inflation is a separate flat factor within the currency; cross-currency basis has special rules. A 5-year OIS hedge may leave curve and maturity basis against a 10-year floating-rate exposure.','Currency-wide signed sum including inflation; excludes cross-currency basis.','12 rate vertices from 2w to 30y; curve correlations multiply tenor correlations. This two-factor experiment uses one currency, a common illustrative weight and one combined correlation.',true,'D · paragraphs 7, 14, 30–36'],
 ['credit-q','Qualifying credit delta','An issuer hedge needs the right seniority and risk mapping.','Credit qualifying separates issuer credit-spread risk by rating and sector buckets. The same issuer/seniority curve can concentrate across tenors and payment currencies. Index decomposition, index vega treatment and base correlation are separate questions.','Issuer and seniority across tenors and payment currencies.','Two tenors of one issuer/seniority curve in one ordinary bucket. Residual, different issuers and index decomposition are taught separately; adjustable correlation is illustrative.',true,'E · paragraphs 8, 15, 37–42'],
 ['credit-nq','Non-qualifying credit delta','A securitisation exposure is not just another corporate name.','Credit non-qualifying captures the specified securitisation credit-spread risk. Ratings and structure determine mapping. Qualifying and non-qualifying risk remain separate risk classes even if their economic drivers overlap.','Issuer / seniority curve; correct securitisation identifier is essential.','Two tenors of one non-qualifying curve. This is not a securitisation tranche pricer or a complete bucket classifier. Do not map all non-investment-grade corporate risk here.',true,'F · paragraphs 8, 16, 43–48'],
 ['equity','Equity delta','An index hedge can leave the stock-specific risk behind.','Equity risk reflects spot sensitivity and bucket characteristics such as market, size and sector. A broad market hedge can offset common exposure without removing single-name concentration. Index, fund and volatility-index treatments have specific rules.','Per equity risk factor after eligible netting.','Two different equity factors in the same ordinary bucket. Inputs are already normalised sensitivity amounts. No dividend-risk pricer, index mapping or volatility-index exception is implemented in this isolated example.',false,'G · paragraphs 8, 17, 49–59'],
 ['commodity','Commodity delta','Two barrels need not represent the same price risk.','Location, grade and delivery conditions can make commodity hedges imperfect. SIMM groups risk by commodity definitions and uses correlations to recognise common movement. The Other bucket and commodity indices have specific treatment.','Per commodity risk factor; do not use total portfolio notional.','Two different factors in one ordinary commodity bucket with an illustrative positive correlation. Full commodity calibration includes special bucket rules not reproduced here.',false,'H · paragraphs 8, 18, 60–64'],
 ['fx','FX delta','Currency exposure depends on the calculation currency.', 'FX delta is expressed against the chosen calculation currency. A currency pair creates linked exposures; it is not a standalone pair risk for delta. FX vega, by contrast, is associated with currency pairs. Changing reporting currency requires consistent transformations, not just relabelling.','Per currency factor; FX volatility categories set thresholds.','Two non-calculation currencies in the FX delta aggregation. FX has no ordinary across-bucket stage in this experiment. Currency-group-dependent weights/correlations are replaced by a visible common illustrative weight.',false,'I · paragraphs 8, 19, 65–73']];
 for(const [id,name,title,simple,group,scope,shared,section] of classes)add({id,name,stage:'04 · The six risk classes',title,intro:'Adjust two signed sensitivities and trace concentration, weighting and aggregation.',inputs:[a('a','Risk factor A sensitivity',-10,10,.5,5),a('b','Risk factor B sensitivity',-10,10,.5,-3),a('rw','Illustrative risk-weight multiplier',.1,3,.1,1,'×'),a('t','Illustrative concentration threshold',.5,20,.5,5),a('rho','Illustrative combined correlation',0,1,.05,.6,'ρ')],challenge:'Try an equal-and-opposite position. Why can margin survive when the factors differ?',formula:'CR → signed WS → covariance aggregation → bucket K and capped S',simple,scope,notes:[['Concentration grouping',group],['Where to verify the full rules',section+' in the linked current methodology. Prescribed tables and all class exceptions are required for production.']],compute(s){const r=M.bucket([s.a,s.b],s.rw,s.t,s.rho,shared);return out(['Weighted A','Weighted B','Bucket K'],[...r.w,r.k],[['CR A / B',r.c.map(n).join(' / '),group],['Correlation factor',n(r.f),'1 when concentration is shared'],['Combined correlation',n(s.rho*r.f),'Illustrative input × concentration adjustment'],['Capped S',n(r.s),'Used at the next applicable aggregation stage']],`${name}: bucket K is ${m(r.k)}. ${shared?'Both factors share the selected concentration group.':'Each factor has its own concentration factor.'} A cross-factor hedge need not cancel completely.`);}});
 add({id:'vega',name:'Vega conventions and weighting',stage:'05 · Optionality and special risks',title:'A quoted vega is only the beginning of volatility risk.',intro:'Convert per-volatility-point vega into volatility-weighted exposure, then apply vega concentration and the vega risk weight.',inputs:[sel('type','Risk class',[['ir','Interest rate'],['eq','Equity (ordinary bucket)'],['co','Commodity'],['fx','FX']],'ir'),a('v','Vega per 1 volatility percentage point',-5,5,.1,1),a('vol','ATM volatility, or prescribed volatility proxy',1,100,1,20,'%'),a('t','Illustrative vega threshold',1,100,1,30)],challenge:'Keep the quoted vega constant but increase the volatility used to scale it.',formula:'Raw exposure = vega per vol point × volatility in % points\nVR = raw × HVR (equity/commodity/FX); weighted VR = VR × VRW × VCR',simple:'SIMM makes vega comparable by combining price sensitivity with a volatility level. Rates and credit use the prescribed ATM volatility convention. Equity, commodity and FX use a proxy derived from delta risk weights, then a historical volatility ratio. A raw vega number cannot safely be dropped into the aggregation without these transformations.',scope:'Single lognormal-volatility example. The volatility control is an illustrative proxy, not an implemented lookup from the delta-weight table. Selected HVR/VRW values are from 2.8+2512: IR VRW .20 (no HVR on vega), equity .56/.29, commodity .81/.34, FX .67/.33. No equity bucket-12, credit, inflation or multi-expiry index exceptions in this calculation.',compute(s){const factors={ir:[1,.20],eq:[.56,.29],co:[.81,.34],fx:[.67,.33]},[h,w]=factors[s.type],raw=s.v*s.vol,vr=raw*h,c=M.cr(vr,s.t),weighted=vr*w*c;return out(['Raw vol risk','HVR-adjusted','Weighted VR'],[raw,vr,weighted],[['HVR',n(h),s.type==='ir'?'Not applied to IR vega':'Prescribed selected class value'],['VRW',n(w),'Selected current calibration'],['VCR',n(c),'Separate vega threshold'],['Standalone vega margin',m(Math.abs(weighted)),'Magnitude after signed processing']],`Vol-weighted exposure is ${m(raw)} and weighted vega is ${m(weighted)}. Matching volatility and derivative units is essential.`);}});
 add({id:'curvature',name:'Curvature, expiry and sign',stage:'05 · Optionality and special risks',title:'Curvature is inferred from volatility risk, with expiry and sign doing real work.',intro:'Follow two volatility-weighted vegas through expiry scaling, squared correlations, theta and lambda.',inputs:[a('a','σ × vega A (before HVR / VRW)',-20,20,.5,10),a('b','σ × vega B (before HVR / VRW)',-20,20,.5,-5),a('da','Option A expiry',14,730,1,365,'calendar days'),a('db','Option B expiry',14,730,1,30,'calendar days'),a('rho','Illustrative correlation',0,1,.05,.5,'ρ'),sel('type','Risk class adjustment',[['other','Non-IR ordinary bucket'],['ir','IR: prescribed HVR = 0.74']],'other')],challenge:'Reverse both exposure signs. Does the curvature margin stay the same?',formula:'CVR = 0.5 min(1,14/expiryDays) × σ × vega\nK² = CVRA² + CVRB² + 2ρ² CVRA CVRB\nθ = min(ΣCVR / Σ|CVR|, 0); λ = (z99.5²−1)(1+θ)−θ\nCurvature = max(ΣCVR + λK, 0); IR multiplies by HVR⁻²',simple:'SIMM does not take a raw gamma input for this charge. It builds a curvature proxy from vega and expiry. Netting before expiry scaling can erase risk incorrectly. The signed sum and tail multiplier make curvature different from a symmetric absolute-value delta charge.',scope:'Two factors in one non-residual bucket; no cross-bucket or residual curvature. No concentration factor, vega risk weight or non-IR HVR is applied to CVR. Equity volatility-index bucket curvature is zero under the methodology and is outside this ordinary-bucket experiment. All-zero CVR uses theta=0 and margin=0.',compute(s){const r=M.curvature(s.a,s.b,s.da,s.db,s.rho,s.type==='ir'?.74:1);return out(['CVR A','CVR B','Curvature'],[r.ca,r.cb,r.margin],[['Scaling A / B',n(.5*Math.min(1,14/s.da))+' / '+n(.5*Math.min(1,14/s.db)),'Apply before expiry netting'],['Squared correlation',n(s.rho*s.rho),'Not the delta correlation'],['Theta / lambda',n(r.theta)+' / '+n(r.lambda),'Portfolio sign affects the tail multiplier'],['Bucket K',m(r.k),'Pre-final curvature aggregation']],`Curvature is ${m(r.margin)}. The signed CVR sum is ${m(r.net)} and theta is ${n(r.theta)}; changing option expiry can alter the hedge even with unchanged vega.`);}});
 add({id:'basis',name:'Inflation and cross-currency basis',stage:'05 · Optionality and special risks',title:'A currency hedge can still leave basis risk.',intro:'Keep an independently weighted basis component while increasing ordinary rate concentration.',inputs:[a('rate','Rate sensitivity',0,20,.5,5),a('inflation','Inflation sensitivity',-10,10,.5,2),a('basis','Already weighted basis component',0,10,.5,2),a('t','Illustrative currency threshold',1,20,.5,5)],challenge:'Increase ordinary rate risk. Does the basis component receive the concentration uplift?',formula:'IR concentration sum includes inflation, excludes cross-currency basis.\nIllustrative K = √[(rate + inflation)² CR² + basisWS²]',simple:'Inflation, ordinary rates and cross-currency basis reflect different economic changes. The cross-currency basis sensitivity is not included in the IR concentration sum and is not multiplied by that concentration factor. Ordinary IR data cannot silently absorb or discard it.',scope:'Mechanism-only illustration: rate and inflation are treated as perfectly correlated and the already weighted basis component as uncorrelated. These are teaching assumptions, not the full prescribed IR covariance matrix. Inflation has its own weight; here rate and inflation weights are both set to 1.',compute(s){const c=M.cr(s.rate+s.inflation,s.t),w=(s.rate+s.inflation)*c,k=M.pair(w,s.basis,0);return out(['Rate + inflation','Basis component','Illustrative K'],[w,s.basis,k],[['Concentration sum',n(s.rate+s.inflation),'Basis excluded'],['CR',n(c),'Basis not scaled'],['Basis WS',m(s.basis),'Already weighted input']],`The currency CR is ${n(c)}, while basis WS remains ${m(s.basis)}. Distinct risk types require distinct treatment.`);}});
 add({id:'base-correlation',name:'Credit base correlation',stage:'05 · Optionality and special risks',title:'A credit tranche can carry correlation risk beyond spread risk.',intro:'Aggregate sensitivities to two credit-index base-correlation families.',inputs:[a('a','Family A BC01',-.5,.5,.01,.10),a('b','Family B BC01',-.5,.5,.01,-.06)],challenge:'Set opposite BC01 amounts. Why does cross-family risk remain?',formula:'WS = 9.7 × BC01; BaseCorrMargin = √(WSA² + WSB² + 2 × 0.10 × WSA × WSB)',simple:'Tranche values depend on how defaults occur together, not just on each name’s spread. Base-correlation risk is an additional Credit Qualifying margin component. It is not the correlation parameter used to aggregate ordinary deltas.',scope:'Two different index families, prescribed 2.8+2512 weight 9.7 and correlation 10%. BC01 is value change for a one-percentage-point increase in base correlation. No concentration uplift. This is not a tranche valuation model.',compute(s){const w=[s.a*9.7,s.b*9.7],k=M.pair(...w,.1);return out(['Weighted A','Weighted B','BaseCorr margin'],[...w,k],[['Risk weight','9.7','Section E paragraph 41'],['Cross-family correlation','10%','Section E paragraph 42'],['Concentration factor','1','Base correlation excluded']],`The additional base-correlation charge is ${m(k)}. Add it to qualifying credit delta, vega and curvature before risk-class aggregation.`);}});
 add({id:'indices',name:'Indices, residuals and mapping',stage:'05 · Optionality and special risks',title:'The way an index is represented changes which offsets are visible.',intro:'Compare a transparent two-constituent delta decomposition with a separate unmatched exposure.',inputs:[a('index','Index weighted delta',0,20,.5,10),a('share','Constituent A share',0,100,5,60,'%'),a('hedge','Single-name A hedge',0,20,.5,6),a('rho','Illustrative constituent correlation',0,1,.05,.4,'ρ')],challenge:'Change the constituent weight while holding the index notional proxy fixed.',formula:'A risk = indexWS × share − hedgeWS\nB risk = indexWS × (1−share); K = covariance aggregate(A,B)',simple:'A constituent hedge becomes visible when the index risk is represented consistently at constituent level. But delta decomposition is not a blanket instruction for index vega and curvature: their special treatments must be checked separately. Unknown classification must be resolved rather than assigned a convenient low-risk bucket.',scope:'Two-name delta-only teaching decomposition, identical weights and no concentration. Actual index/fund eligibility, look-through and residual rules depend on the risk class and methodology. This experiment does not automatically classify or price an index.',compute(s){const x=s.index*s.share/100-s.hedge,y=s.index*(1-s.share/100),k=M.pair(x,y,s.rho);return out(['Residual A','Constituent B','Decomposed K'],[x,y,k],[['Index A contribution',m(s.index*s.share/100),'Before hedge'],['Hedge A',m(s.hedge),'Only matches the correct constituent'],['Unmatched gross comparison',m(s.index+s.hedge),'No recognised decomposition or offset']],`After matching the A hedge, ${m(x)} of A and ${m(y)} of B remain. A correct mapping can explain a margin break; false mapping can hide one.`);}});
 add({id:'total',name:'From risk classes to total IM',stage:'06 · Portfolio and collateral',title:'Diversify within a product class, then add product classes.',intro:'Combine rates and FX margin inside RatesFX, then add other product-class totals.',inputs:[a('ir','IR risk-class IM in RatesFX',0,20,.5,8),a('fx','FX risk-class IM in RatesFX',0,20,.5,5),a('credit','Credit product-class total',0,20,.5,3),a('equity','Equity product-class total',0,20,.5,2),a('commodity','Commodity product-class total',0,20,.5,1)],challenge:'Compare the sum of IR and FX with their diversified RatesFX total.',formula:'RatesFX = √(IMIR² + IMFX² + 2 × 0.15 × IMIR × IMFX)\nTotal = RatesFX + Credit product + Equity product + Commodity product',simple:'Delta, vega, curvature and applicable base correlation are added to form a risk-class margin. Risk classes then diversify using the prescribed matrix within each product class. Finally, product-class totals are added without cross-product diversification.',scope:'IR–FX correlation 15% from section K, 2.8+2512. Other product-class totals are supplied inputs, assumed already calculated with their own risk-class composition. No add-ons or threshold deduction in this lesson.',compute(s){const r=M.pair(s.ir,s.fx,.15),total=r+s.credit+s.equity+s.commodity;return out(['RatesFX','Credit','Equity','Commodity','Total SIMM'],[r,s.credit,s.equity,s.commodity,total],[['Undiversified IR + FX',m(s.ir+s.fx),'Same product class'],['RatesFX benefit',m(s.ir+s.fx-r),'Selected prescribed correlation'],['Across product classes','Add totals','No cross-product covariance term']],`Total sensitivity-based margin is ${m(total)}. The ${m(s.ir+s.fx-r)} benefit occurs inside RatesFX, not across the four product classes.`,[['RatesFX',m(r)],['Other product classes',m(s.credit+s.equity+s.commodity)],['Total SIMM',m(total)]]);}});
 add({id:'incremental',name:'Hedge and incremental IM sandbox',stage:'06 · Portfolio and collateral',title:'The cost of a new trade depends on the book it joins.',intro:'Add a signed hedge to one factor and compare standalone, before and after margin.',inputs:[a('a','Existing factor A risk',-20,20,.5,10),a('b','Existing factor B risk',-20,20,.5,6),a('trade','New trade factor A risk',-20,20,.5,-5),a('rho','Illustrative factor correlation',0,1,.05,.5,'ρ'),a('t','Illustrative concentration threshold',1,30,1,10)],challenge:'Increase the hedge past a full offset. Can the incremental margin turn positive again?',formula:'Incremental IM = IM(existing + trade) − IM(existing)\nStandalone IM = IM(trade alone)',simple:'A trade may add risk by itself and reduce risk inside a portfolio. Incremental margin captures that interaction, including concentration. A negative increment is a reduction in the requirement, not permission to net the two parties’ posted IM balances.',scope:'Two non-IR factors in one ordinary bucket with unit weights. Delta only; no product-class boundaries, transaction costs, liquidity or valuation effects. This sandbox is an educational comparison, not an execution recommendation.',compute(s){const before=M.bucket([s.a,s.b],1,s.t,s.rho).k,after=M.bucket([s.a+s.trade,s.b],1,s.t,s.rho).k,stand=Math.abs(s.trade)*M.cr(s.trade,s.t);return out(['Before','After','Incremental','Standalone'],[before,after,after-before,stand],[['Eligible net A',n(s.a+s.trade),'After adding the trade'],['Incremental',m(after-before),'Can be negative'],['Standalone',m(stand),'Does not measure portfolio impact']],`The new trade changes IM by ${m(after-before)}, compared with standalone margin ${m(stand)}. An excessive hedge can create a new concentrated position.`);}});
 add({id:'addons',name:'Additional margin and remediation',stage:'06 · Portfolio and collateral',title:'A model shortfall needs an explicit, traceable adjustment.',intro:'Apply a product-class multiplier, a fixed add-on and a gross-notional add-on.',inputs:[a('base','Product-class SIMM',0,30,.5,10),a('mult','Agreed multiplicative scale',1,2,.05,1.1,'×'),a('fixed','Fixed add-on',0,10,.5,1),a('notional','Affected gross notional',0,500,10,100),a('factor','Notional add-on factor',0,5,.1,.5,'%')],challenge:'Offset the trades economically but retain their gross notionals. Does a gross-notional add-on vanish?',formula:'Additional IM = fixed + factor × gross notional + (scale−1) × product SIMM\nTotal = base SIMM + additional IM',simple:'A standard sensitivity calculation may not adequately cover every portfolio. Remediation can use transparent additional amounts or product-class scales. These adjustments should be explained and agreed through governance, not buried inside unexplained sensitivity edits.',scope:'Section L structure for one product class; parameters are illustrative agreed inputs, not automatic regulatory factors. Gross notional is the sum of absolute current notionals for affected products. Multipliers have a minimum of 1.',sources:[refs.method,refs.gov],compute(s){const add=s.fixed+s.notional*s.factor/100+(s.mult-1)*s.base;return out(['Base SIMM','Additional IM','Total'],[s.base,add,s.base+add],[['Multiplier increment',m((s.mult-1)*s.base),'Not the whole scaled base again'],['Notional add-on',m(s.notional*s.factor/100),'Uses gross affected notional'],['Fixed component',m(s.fixed),'Separately agreed']],`The additional amount is ${m(add)}, giving ${m(s.base+add)} total. The trace separates each source of the adjustment.`);}});
 add({id:'collateral',name:'Threshold, MTA and eligible collateral',stage:'06 · Portfolio and collateral',title:'The model requirement is not the same as today’s collateral transfer.',intro:'Translate an illustrative margin requirement into a one-direction top-up after a threshold, existing collateral and haircut.',inputs:[a('im','Model IM requirement',0,100,1,60),a('threshold','Allocated IM threshold',0,50,1,50),a('held','Collateral market value held',0,50,1,5),a('haircut','Collateral haircut',0,30,1,5,'%'),a('mta','Illustrative minimum transfer amount',0,2,.1,.5)],challenge:'Keep model IM unchanged and increase the collateral haircut.',formula:'Requirement after threshold = max(IM − threshold,0)\nRecognised collateral = market value × (1−haircut)\nIf shortfall ≥ MTA, nominal top-up = shortfall / (1−haircut)',simple:'The model estimates risk. Agreements and applicable rules determine the threshold allocation, transfer mechanics and acceptable assets. Haircuts reduce recognised collateral value, so the same model requirement may require more securities to be delivered.',scope:'One-way top-up only, no returns, FX haircut, rounding, disputes or settlement lag. Inputs are illustrative; the BCBS–IOSCO framework threshold is applied at consolidated-group level and cannot be freely duplicated across counterparties. MTA may apply to combined IM/VM under applicable documentation. This is not legal eligibility assessment.',sources:[refs.margin],compute(s){const req=Math.max(s.im-s.threshold,0),rec=s.held*(1-s.haircut/100),short=Math.max(req-rec,0),top=short>=s.mta?short/(1-s.haircut/100):0;return out(['Required coverage','Recognised held','Nominal top-up'],[req,rec,top],[['Model IM',m(s.im),'Unaffected by operational threshold'],['Coverage shortfall',m(short),'Before MTA'],['Transfer',top?m(top):'No top-up','Illustrative top-up rule only']],`Model IM remains ${m(s.im)}. The selected operational assumptions produce a nominal top-up of ${m(top)}.`);}});
 add({id:'two-way',name:'Two-way IM and funding',stage:'06 · Portfolio and collateral',title:'Receiving IM does not necessarily fund the IM you post.',intro:'Track two separate collateral directions and estimate the funding cost of your posted balance.',inputs:[a('post','IM posted by you',0,30,.5,12),a('receive','IM received by you',0,30,.5,10),a('spread','Illustrative annual funding spread',0,5,.1,1,'%'),a('years','Funding horizon',.5,5,.5,1,'years')],challenge:'Make received IM equal posted IM. Does the posted collateral funding need disappear?',formula:'Undiscounted funding proxy = posted IM × annual spread × years',simple:'Bilateral IM is normally exchanged in separate protected arrangements. You should not assume the collateral received can simply be reused to meet your posting obligation. Portfolio sign effects can also make the two calculated requirements differ, especially for curvature.',scope:'Constant posted IM and funding spread; received collateral assumed unavailable for reuse. No stochastic future IM, discounting, tax or detailed segregation-law assessment. MVA valuation is covered in the XVA path.',sources:[refs.margin,refs.method],compute(s){return out(['Posted','Received','Funding proxy'],[s.post,s.receive,s.post*s.spread/100*s.years],[['Net accounting comparison',m(s.post-s.receive),'Does not define available funding'],['Funding base',m(s.post),'Posted balance under these assumptions'],['Annual spread',s.spread+'%','Illustrative financing input']],`Even with ${m(s.receive)} received, this example funds ${m(s.post)} posted. The simple funding proxy is ${m(s.post*s.spread/100*s.years)}.`);}});
 add({id:'crif',name:'CRIF and reconciliation',stage:'07 · Data, validation and governance',title:'Reconcile the risk record before debating the final margin.',intro:'Inject a missing hedge, a unit error or an FX conversion mismatch into a two-record risk set.',inputs:[a('a','Trade A sensitivity in USD m',0,20,.5,10),a('b','Trade B offset in USD m',-20,0,.5,-8),sel('error','Counterparty data issue',[['none','Aligned data'],['missing','Hedge record missing'],['units','Hedge multiplied by 100'],['fx','Hedge currency conversion 10% high']],'none')],challenge:'Which break should you investigate first: the headline margin or the unmatched record?',formula:'Teaching comparison: IM = |Σ normalised same-factor sensitivities|, RW = 1 and no concentration',simple:'CRIF gives counterparties a common language for exchanging risk. Matching trade population, product class, risk type, qualifier, bucket, tenor, sub-curve and amount currency makes the final number explainable. A shared file format does not prove the underlying pricing or mapping is correct.',scope:'Synthetic CRIF-inspired trace, not a complete import/export schema validator. Same-factor delta comparison only. No real portfolio upload or server processing. Full CRIF version and required fields must be agreed independently.',sources:[refs.data,refs.method],compute(s){const b=s.error==='missing'?0:s.b*(s.error==='units'?100:s.error==='fx'?1.1:1),ours=Math.abs(s.a+s.b),theirs=Math.abs(s.a+b);return out(['Your result','Other result','Difference'],[ours,theirs,theirs-ours],[['Trade A / Trade B',n(s.a)+' / '+n(b),'Normalised USD amounts received'],['Identity fields','RatesFX · Risk_IRCurve · USD · 5y · OIS','Illustrative shared factor key'],['Reconciliation status',s.error==='none'?'Aligned':'Investigate '+s.error,'Do not repair by overwriting final IM']],`The ${m(theirs-ours)} difference comes from ${s.error==='none'?'no injected data error':'the injected '+s.error+' issue'}, despite using the same simplified aggregation formula.`);}});
 add({id:'regridding',name:'Tenor mapping and risk preservation',stage:'07 · Data, validation and governance',title:'Preserve the risk when moving it onto standard vertices.',intro:'Split an off-grid rate sensitivity between 5-year and 10-year vertices using an explicit teaching interpolation.',inputs:[a('s','Off-grid sensitivity',-10,10,.5,5),a('tenor','Original tenor',5,10,.5,7,'years'),a('rw5','Illustrative 5y risk weight',.1,2,.1,1,'×'),a('rw10','Illustrative 10y risk weight',.1,2,.1,1.2,'×')],challenge:'Slide the tenor toward 10 years and watch where the risk goes.',formula:'w5 = (10−t)/5; w10 = (t−5)/5\ns5 = w5 × s; s10 = w10 × s; s5 + s10 = s',simple:'Risk engines and standard models may use different grids. Re-expression should preserve the intended risk behaviour and use a consistent documented convention. Snapping everything to the nearest tenor creates abrupt changes and can misrepresent a hedge.',scope:'Linear tenor allocation illustrates conservation; it is not asserted to be the complete ISDA risk-data-standard regridding algorithm for every instrument. Price-based risk transformations and curve conventions need independent validation. Weighted contributions shown separately, not a full margin.',sources:[refs.data,refs.method],compute(s){const x=s.s*(10-s.tenor)/5,y=s.s*(s.tenor-5)/5;return out(['5y sensitivity','10y sensitivity','Preserved sum'],[x,y,x+y],[['5y weighted contribution',n(x*s.rw5),'Not aggregated yet'],['10y weighted contribution',n(y*s.rw10),'Different weights change the weighted sum'],['Conservation error',n(x+y-s.s),'Should be zero']],`The original ${n(s.s)} sensitivity is preserved as ${n(x)} at 5y plus ${n(y)} at 10y. Conservation alone does not validate valuation accuracy.`);}});
 add({id:'backtesting',name:'Coverage and backtesting',stage:'07 · Data, validation and governance',title:'A plausible margin number still needs evidence of coverage.',intro:'Count exceedances in a fixed synthetic set of 250 ten-day losses as you change the margin buffer and stress severity.',inputs:[a('im','Margin buffer',1,20,.5,8),a('stress','Synthetic tail severity',.5,3,.1,1,'×')],challenge:'Can a low breach count hide one very large uncovered loss?',formula:'Exceedance = ten-day loss > margin\nObserved coverage = 1 − exceedance count / observation count',simple:'Backtesting asks whether the margin would have covered observed adverse moves. Breach count, breach size, market regime and data quality all matter. Overlapping horizons create dependent observations, so a percentage alone is not a statistical approval test.',scope:'Deterministic synthetic sample, not historical data or official SIMM governance traffic lights. The full governance framework specifies monitoring, portfolio assessment and remediation requirements beyond this diagnostic.',sources:[refs.gov,refs.method],compute(s){const losses=Array.from({length:250},(_,i)=>s.stress*(1+3*Math.abs(Math.sin(i*2.399))+(i%61===0?8:i%29===0?4:0))),count=losses.filter(x=>x>s.im).length,worst=Math.max(...losses);return {stats:[['Exceedances',count+' / 250'],['Observed coverage',(100*(1-count/250)).toFixed(1)+'%'],['Largest shortfall',m(Math.max(0,worst-s.im))]],series:[{name:'Synthetic 10-day loss',color:'#7597ac',data:losses.map((x,i)=>[i+1,x]),dots:true},{name:'Margin buffer',color:'#285e46',data:[[1,s.im],[250,s.im]]}],xlabel:'Synthetic observation',headers:['Diagnostic','Value','Meaning'],rows:[['Largest loss',m(worst),'Severity matters alongside frequency'],['Exceedance count',count,'No official pass/fail inferred'],['Data source','Invented deterministic scenarios','Not market evidence']],explanation:`${count} losses exceed the buffer. This is a diagnostic experiment, not a conclusion that a real portfolio passes SIMM governance.`};}});
 add({id:'versions',name:'Calibration changes and governance',stage:'07 · Data, validation and governance',title:'Separate market moves from model-version moves.',intro:'Hold the portfolio constant while changing a risk weight, then isolate a sensitivity change.',inputs:[a('s','Original net sensitivity',0,20,.5,5),a('old','Illustrative old weight',.1,2,.1,1,'×'),a('new','Illustrative new weight',.1,2,.1,1.2,'×'),a('move','Sensitivity change',-5,5,.5,1)],challenge:'Freeze sensitivities first. How much of the margin change comes only from the weight?',formula:'Old = |s × oldRW|\nRecalibration-only = |s × newRW|\nFinal = |(s + Δs) × newRW|',simple:'An IM move can come from new trades, market data, pricing changes, risk mapping, FX conversion or a calibration release. Replaying the same risk set through both versions isolates model change. Both counterparties need aligned versions and effective dates.',scope:'One factor, no concentration or correlation changes; old/new weights are deliberately illustrative, not historical version values. The current reference release is 2.8+2512, effective 11 July 2026. A release comparison must load complete versioned parameter sets.',sources:[refs.method,['https://www.isda.org/2026/06/12/isda-publishes-isda-simm-methodology-version-2-8-2512/','ISDA · release and effective date'],refs.gov],compute(s){const old=Math.abs(s.s*s.old),fixed=Math.abs(s.s*s.new),final=Math.abs((s.s+s.move)*s.new);return out(['Old result','New calibration','Final result'],[old,fixed,final],[['Calibration contribution',m(fixed-old),'Frozen portfolio'],['Sensitivity contribution',m(final-fixed),'New calibration held fixed'],['Total change',m(final-old),'Order-specific attribution reconciles exactly']],`Of the ${m(final-old)} total change, ${m(fixed-old)} is the isolated weight change. Preserve inputs, version, valuation time and scope with every calculation.`);}});
})();
